 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='question-forms' AND (catalog_hash<>'e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' OR payload_md5<>'534a923baf16f637ddcf8b968fab8a51')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
