INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','question-forms','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"question-forms","title":"Questions, question words and short answers","level":"A1","order":11,"summary":"Build direct questions and distinguish a question about the subject from one about the object.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Use the existing auxiliary","Add do when needed","Subject questions","Short answers"],"rules":[{"title":"Use the existing auxiliary","explanation":"If a statement already has be, a modal or an auxiliary have, put the first auxiliary before the subject. The rest of the verb phrase remains after the subject. A question word, if needed, normally comes first.","pattern":"**Are** they ready? / Where **have** they gone?","commonMistakes":["Do not add do to a question already built with auxiliary be: Are they waiting?, not Do they are waiting?"],"examples":["Present simple: “**Does** the assistant prepare the visitor guide every day?”","Present simple: “**Does** the assistant restore the old portrait every day?”"],"skill":"form"},{"title":"Add do when needed","explanation":"For an ordinary present-simple action verb, add **do / does**. For past simple, add **did**. These auxiliaries carry tense and agreement, so the main verb uses its base form.","pattern":"Where **does** she **work**? / What **did** they **buy**?","commonMistakes":["Does she works? marks agreement twice. Keep the -s on does, not on the main verb."],"examples":["Complete the past-simple question: “Why did the assistant **prepare** the visitor guide?”","Complete the past-simple question: “Why did the assistant **restore** the old portrait?”"],"skill":"meaning"},{"title":"Subject questions","explanation":"When who or what is itself the subject, a neutral affirmative question usually has normal subject–verb order without do. Compare Who called you? with Who did you call? The person sought has a different role.","pattern":"**Who called**? / **Who did you call**?","commonMistakes":["Emphatic subject questions can use do, as in Who did call? These exercises practise the neutral pattern."],"examples":["Ask who performs the action, in the neutral present simple: “Who **prepares** the visitor guide each morning?”","Ask who performs the action, in the neutral present simple: “Who **restores** the old portrait each morning?”"],"skill":"contrast"},{"title":"Short answers","explanation":"Use a pronoun and the same auxiliary family as the question: Do they work? Yes, they do. Can she swim? No, she can’t. In a positive short answer, keep the auxiliary full rather than ending with a contraction.","pattern":"Yes, she **does**. / No, they **did not**.","commonMistakes":["Yes, she’s is not a normal complete positive short answer to Is she ready? Use Yes, she is."],"examples":["“Did they prepare the visitor guide yesterday?” Complete the positive short answer: “Yes, they **did**.”","“Did they restore the old portrait yesterday?” Complete the positive short answer: “Yes, they **did**.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"70dacbf0-5850-5f98-a61a-64133db13485","topicSlug":"question-forms","level":"A1","prompt":"Present simple: “____ the assistant prepare the visitor guide every day?”","choices":[{"id":"A","text":"Is"},{"id":"B","text":"Has"},{"id":"C","text":"Does"},{"id":"D","text":"Do"}],"answerId":"C","hint":"Find the subject’s number, then choose **do or does**.","explanation":"The singular subject **the assistant** takes **does**; prepare stays in the base form.","keywords":["present-question-auxiliary"],"skill":"present-question-auxiliary","contextKey":"question-forms-1","fingerprint":"87e43fe09e1d9bdc966f7eddbac7927fc30eb00010289d9bacbef2db03c4251d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject’s number, then choose **do or does**.","The singular subject **the assistant** takes **does**; prepare stays in the base form.","Choose **Does**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The lexical verb is in base form, so is cannot make this present-simple question.","B":"Has would require a participle for a perfect question, not this present-simple construction.","C":"The singular subject **the assistant** takes **does**; prepare stays in the base form.","D":"Do does not agree with the singular third-person subject."}}},{"id":"3145c10d-ad08-5864-a93f-93992d6e3418","topicSlug":"question-forms","level":"A1","prompt":"Complete the past-simple question: “Why did the assistant ____ the visitor guide?”","choices":[{"id":"A","text":"been prepare"},{"id":"B","text":"prepare"},{"id":"C","text":"prepares"},{"id":"D","text":"to prepare"}],"answerId":"B","hint":"The past marker is already on **did**; do not mark it twice.","explanation":"**Did** carries the past tense, so choose base **prepare**.","keywords":["past-question-base"],"skill":"past-question-base","contextKey":"question-forms-1","fingerprint":"9bcd8099c9ff37dfba493b64337e80a9bb778f610ba05a8b2598e8c57b20a291","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past marker is already on **did**; do not mark it twice.","**Did** carries the past tense, so choose base **prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Been cannot follow did to build this question.","B":"**Did** carries the past tense, so choose base **prepare**.","C":"The third-person -s form cannot follow did in this question.","D":"Did takes a bare infinitive, without to."}}},{"id":"5b7790a5-e3ee-5bb5-a4ba-633dddbf8213","topicSlug":"question-forms","level":"A1","prompt":"Ask who performs the action, in the neutral present simple: “Who ____ the visitor guide each morning?”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepares"},{"id":"C","text":"does prepares"},{"id":"D","text":"is prepare"}],"answerId":"B","hint":"The missing person is the **subject**, not the object.","explanation":"**Who** is the subject, so use the singular present form **prepares** without an extra do.","keywords":["subject-question"],"skill":"subject-question","contextKey":"question-forms-1","fingerprint":"470f90661b579d75bb72ca070a04d3ef935fa3c53ab4ddce3f8cc97c8668fc55","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The missing person is the **subject**, not the object.","**Who** is the subject, so use the singular present form **prepares** without an extra do.","Choose **prepares**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive is not a finite predicate after who.","B":"**Who** is the subject, so use the singular present form **prepares** without an extra do.","C":"This marks the main verb as well as adding does; the form after does would have to be base.","D":"Is cannot take this base action verb in a neutral present-simple question."}}},{"id":"bf0ebd70-54b4-5906-adeb-997bee794fb2","topicSlug":"question-forms","level":"A1","prompt":"“Did they prepare the visitor guide yesterday?” Complete the positive short answer: “Yes, they ____.”","choices":[{"id":"A","text":"did"},{"id":"B","text":"do"},{"id":"C","text":"were"},{"id":"D","text":"have"}],"answerId":"A","hint":"Match the short answer’s auxiliary to the question.","explanation":"Repeat **did**, the auxiliary from the past-simple question.","keywords":["matching-short-answer"],"skill":"matching-short-answer","contextKey":"question-forms-1","fingerprint":"84df2367f6811935c76809b56d57fbfbd3654f663620f9510745853f4f61c988","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the short answer’s auxiliary to the question.","Repeat **did**, the auxiliary from the past-simple question.","Choose **did**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Repeat **did**, the auxiliary from the past-simple question.","B":"Do changes the short answer to present time.","C":"Were does not match the auxiliary family of this question.","D":"Have would answer a perfect question, not one beginning with did."}}},{"id":"bdc3b34d-d0dc-570b-aea6-f775d0819e6c","topicSlug":"question-forms","level":"A1","prompt":"Present simple: “____ the assistant restore the old portrait every day?”","choices":[{"id":"A","text":"Has"},{"id":"B","text":"Does"},{"id":"C","text":"Do"},{"id":"D","text":"Is"}],"answerId":"B","hint":"Find the subject’s number, then choose **do or does**.","explanation":"The singular subject **the assistant** takes **does**; restore stays in the base form.","keywords":["present-question-auxiliary"],"skill":"present-question-auxiliary","contextKey":"question-forms-2","fingerprint":"01483f7a6e92075b6b5098ac56397cae6de52af86d7cb7e5bc74a6554b0265c3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject’s number, then choose **do or does**.","The singular subject **the assistant** takes **does**; restore stays in the base form.","Choose **Does**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Has would require a participle for a perfect question, not this present-simple construction.","B":"The singular subject **the assistant** takes **does**; restore stays in the base form.","C":"Do does not agree with the singular third-person subject.","D":"The lexical verb is in base form, so is cannot make this present-simple question."}}},{"id":"7594e137-497a-5f60-a772-786fd340b1e9","topicSlug":"question-forms","level":"A1","prompt":"Complete the past-simple question: “Why did the assistant ____ the old portrait?”","choices":[{"id":"A","text":"been restore"},{"id":"B","text":"restore"},{"id":"C","text":"restores"},{"id":"D","text":"to restore"}],"answerId":"B","hint":"The past marker is already on **did**; do not mark it twice.","explanation":"**Did** carries the past tense, so choose base **restore**.","keywords":["past-question-base"],"skill":"past-question-base","contextKey":"question-forms-2","fingerprint":"47a016d2a97d50c9e2853949f853b2e4806f7d26d99113563929882157a8de02","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past marker is already on **did**; do not mark it twice.","**Did** carries the past tense, so choose base **restore**.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Been cannot follow did to build this question.","B":"**Did** carries the past tense, so choose base **restore**.","C":"The third-person -s form cannot follow did in this question.","D":"Did takes a bare infinitive, without to."}}},{"id":"025fce75-1e25-5bd6-a5ea-3868077ce6dc","topicSlug":"question-forms","level":"A1","prompt":"Ask who performs the action, in the neutral present simple: “Who ____ the old portrait each morning?”","choices":[{"id":"A","text":"does restores"},{"id":"B","text":"is restore"},{"id":"C","text":"to restore"},{"id":"D","text":"restores"}],"answerId":"D","hint":"The missing person is the **subject**, not the object.","explanation":"**Who** is the subject, so use the singular present form **restores** without an extra do.","keywords":["subject-question"],"skill":"subject-question","contextKey":"question-forms-2","fingerprint":"c80777b3a532eb8c8fb7ac76c925a515480f89fdab285485a5d342809c50574a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The missing person is the **subject**, not the object.","**Who** is the subject, so use the singular present form **restores** without an extra do.","Choose **restores**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This marks the main verb as well as adding does; the form after does would have to be base.","B":"Is cannot take this base action verb in a neutral present-simple question.","C":"A to-infinitive is not a finite predicate after who.","D":"**Who** is the subject, so use the singular present form **restores** without an extra do."}}},{"id":"cf88d87b-266b-5be8-a5ac-7141b055b4e7","topicSlug":"question-forms","level":"A1","prompt":"“Did they restore the old portrait yesterday?” Complete the positive short answer: “Yes, they ____.”","choices":[{"id":"A","text":"do"},{"id":"B","text":"were"},{"id":"C","text":"have"},{"id":"D","text":"did"}],"answerId":"D","hint":"Match the short answer’s auxiliary to the question.","explanation":"Repeat **did**, the auxiliary from the past-simple question.","keywords":["matching-short-answer"],"skill":"matching-short-answer","contextKey":"question-forms-2","fingerprint":"a0b9943ab1a0f0f5bb140bc7dba7871a8dab87c7b4aa9f5b7f790bec1baf8d8c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the short answer’s auxiliary to the question.","Repeat **did**, the auxiliary from the past-simple question.","Choose **did**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do changes the short answer to present time.","B":"Were does not match the auxiliary family of this question.","C":"Have would answer a perfect question, not one beginning with did.","D":"Repeat **did**, the auxiliary from the past-simple question."}}},{"id":"84a4466d-75cb-577f-abee-95d17cdbdfcb","topicSlug":"question-forms","level":"A1","prompt":"Present simple: “____ the assistant measure the garden fence every day?”","choices":[{"id":"A","text":"Is"},{"id":"B","text":"Has"},{"id":"C","text":"Does"},{"id":"D","text":"Do"}],"answerId":"C","hint":"Find the subject’s number, then choose **do or does**.","explanation":"The singular subject **the assistant** takes **does**; measure stays in the base form.","keywords":["present-question-auxiliary"],"skill":"present-question-auxiliary","contextKey":"question-forms-3","fingerprint":"7f8116afbbf87a502a03d0826ad004917c3223fa1087a2978181a6f0db61940f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject’s number, then choose **do or does**.","The singular subject **the assistant** takes **does**; measure stays in the base form.","Choose **Does**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReaso