 IF EXISTS(SELECT 1 FROM grammar.grammar_topics WHERE slug='question-forms' AND source_metadata->>'version' IS DISTINCT FROM 'core-2026-09-v3') THEN RAISE EXCEPTION 'Topic belongs to another release'; END IF;
