INSERT INTO grammar.grammar_topics(slug,title,level,order_index,summary,guidance,learning_goals,rules,tips,source,source_metadata)
SELECT j->>'slug',j->>'title',j->>'level',(j->>'order')::integer,j->>'summary',j->>'guidance',ARRAY(SELECT jsonb_array_elements_text(j->'learningGoals')),j->'rules',ARRAY(SELECT jsonb_array_elements_text(j->'tips')),'seed','{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending","contentHash":"e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4","sources":[{"id":"bc-question-forms","title":"Question forms","url":"https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/question-forms","publisher":"British Council LearnEnglish","use":"Grammar guidance and scope only. Original explanations and practice; no publisher exercise reproduced.","reviewedOn":"2026-09-13"}]}'::jsonb FROM (SELECT payload j FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='question-forms') p
ON CONFLICT(slug) DO NOTHING;
INSERT INTO grammar.grammar_quiz_items(id,topic_slug,level,prompt,choices,answer_id,hint,explanation,keywords,source,fingerprint,source_metadata)
SELECT (q->>'id')::uuid,q->>'topicSlug',q->>'level',q->>'prompt',q->'choices',q->>'answerId',q->>'hint',q->>'explanation',ARRAY(SELECT jsonb_array_elements_text(q->'keywords')),'seed',q->>'fingerprint',(q->'provenance')||jsonb_build_object('contentHash','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','skill',q->>'skill','contextKey',q->>'contextKey','teaching',q->'teaching')
FROM grammar.content_catalog_topics t CROSS JOIN LATERAL jsonb_array_elements(t.payload->'quizItems') q WHERE t.version='core-2026-09-v3' AND t.slug='question-forms'
ON CONFLICT(id) DO NOTHING;
DO $verify$ BEGIN
